//! Emoji shortcodes for an incident kind — the lock-screen icon.

use bsc_incident::Kind;

/// Emoji shortcodes for a kind — the icon on the lock screen. Always non-empty so a notification is
/// never faceless. An explicit match, not a wildcard, so a new kind must choose its own face here.
pub fn tags_for(kind: Kind) -> Vec<String> {
    let s: &[&str] = match kind {
        Kind::DeauthFlood => &["rotating_light", "satellite_antenna"],
        Kind::Jamming => &["rotating_light", "no_entry"],
        Kind::ScanDetected => &["mag", "warning"],
        Kind::RogueDhcp => &["warning", "satellite"],
        Kind::LeaseTheft => &["warning", "busts_in_silhouette"],
        Kind::NewDevice => &["bust_in_silhouette"],
        Kind::Impact => &["rotating_light", "boom"],
        Kind::Distress => &["rotating_light", "loudspeaker"],
        Kind::UnknownVoice => &["warning", "speaking_head"],
        Kind::Other => &["warning"],
    };
    s.iter().map(|t| (*t).to_string()).collect()
}
